CREATE OR REPLACE FUNCTION public.is_qualified_investor() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT auth.uid() IS NOT NULL AND private.has_role(auth.uid(),'investor') AND EXISTS(SELECT 1 FROM auth.users u JOIN public.investor_profiles i ON i.user_id=u.id WHERE u.id=auth.uid() AND u.email_confirmed_at IS NOT NULL AND nullif(btrim(i.company_name),'') IS NOT NULL AND u.email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' AND lower(split_part(u.email,'@',2)) <> ALL(ARRAY['gmail.com','googlemail.com','yahoo.com','yahoo.co.uk','yahoo.fr','hotmail.com','hotmail.co.uk','outlook.com','outlook.fr','live.com','msn.com','icloud.com','me.com','mac.com','aol.com','proton.me','protonmail.com','pm.me','gmx.com','gmx.de','mail.com','yandex.com','yandex.ru','qq.com','163.com','126.com','mail.ru','tutanota.com','tuta.com','fastmail.com','zoho.com','guerrillamail.com','mailinator.com','10minutemail.com','tempmail.com']) AND i.mandate_reviewed_at IS NOT NULL AND i.investor_type IS NOT NULL AND i.ticket_band IS NOT NULL AND cardinality(i.matched_instruments)>0 AND cardinality(i.regions_of_interest)>0 AND i.construction_risk_appetite IS NOT NULL AND i.capital_source IS NOT NULL AND i.decision_process IS NOT NULL AND i.earliest_stage IS NOT NULL); $$;
REVOKE ALL ON FUNCTION public.is_qualified_investor() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.is_qualified_investor() TO authenticated,service_role;
DO $patch$ DECLARE d text;r record; BEGIN
FOR r IN SELECT oid FROM pg_proc WHERE oid IN ('public.subscriber_document(jsonb,boolean)'::regprocedure,'public.subscriber_project(uuid)'::regprocedure,'public.subscriber_document_index(uuid)'::regprocedure) LOOP SELECT pg_get_functiondef(r.oid) INTO d;d:=replace(replace(replace(replace(d,'subscriber_document','investor_document'),'subscriber_project','investor_project'),'is_subscriber','is_qualified_investor'),'An active subscription is required','Complete your investment mandate to open this');EXECUTE d;END LOOP;
FOR r IN SELECT tablename,policyname,qual,with_check FROM pg_policies WHERE schemaname='public' AND policyname IN ('paid_depth','subscriber_interest_submission') LOOP IF r.qual IS NOT NULL THEN EXECUTE format('ALTER POLICY %I ON public.%I USING (%s)',r.policyname,r.tablename,replace(r.qual,'is_subscriber()','is_qualified_investor()')); END IF;IF r.with_check IS NOT NULL THEN EXECUTE format('ALTER POLICY %I ON public.%I WITH CHECK (%s)',r.policyname,r.tablename,replace(r.with_check,'is_subscriber()','is_qualified_investor()'));END IF;END LOOP;
SELECT pg_get_functiondef('public.save_stage_listing(jsonb,jsonb,uuid,boolean,integer)'::regprocedure) INTO d;d:=replace(replace(replace(d,'subscriberPreviewConsent','investorPreviewConsent'),'subscriber disclosure preview','qualified investor disclosure preview'),'public.subscriber_document(','public.investor_document(');EXECUTE d;
END $patch$;
REVOKE ALL ON FUNCTION public.investor_document(jsonb,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.investor_document(jsonb,boolean) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.investor_project(uuid),public.investor_document_index(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.investor_project(uuid),public.investor_document_index(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.is_subscriber() RETURNS boolean LANGUAGE sql STABLE SET search_path='' AS $$ SELECT false; $$;
REVOKE ALL ON FUNCTION public.is_subscriber() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.is_subscriber() TO authenticated;
REVOKE ALL ON public.subscription FROM anon,authenticated,service_role;
COMMENT ON TABLE public.subscription IS 'DEPRECATED: no subscription charge or billing. Access uses is_qualified_investor. Retained only as inactive additive migration history.';
COMMENT ON FUNCTION public.is_subscriber() IS 'DEPRECATED: retired payment gate. Application uses is_qualified_investor.';